// ─── Travel Ticker Component (LED departure board style) ─────────────────────
function TravelTicker({ event, colors }: { event: ScheduleEvent; colors: any }) {
  const { isPaper, isEightBit, isTerminal, tokens: skinTokens } = useSkin();
  const [now, setNow] = useState(Date.now());
  const [weather, setWeather] = useState<{ tempF: number; icon: string; label: string } | null>(null);
  const eventColor = event.color || colors.primary;
  // Under 8-bit the strip is the mockup's dark HUD panel: segments
  // read in light lavender against the dusk ground, whatever the
  // event's own color is. Under Terminal the strip is a status line
  // on the tube: phosphor segments, whatever the event's color is.
  const tickerInk = isTerminal ? TERM_PHOS : isEightBit ? "#EDE8FF" : eventColor;
  const translateX = useSharedValue(0);
  const [contentWidth, setContentWidth] = useState(0);

  // Update countdown every 30 seconds
  useEffect(() => {
    const interval = setInterval(() => setNow(Date.now()), 30000);
    return () => clearInterval(interval);
  }, []);

  // Fetch weather for location
  useEffect(() => {
    if (event.location) {
      import("@/lib/weather").then(({ getWeatherForLocation }) => {
        getWeatherForLocation(event.location!).then(setWeather);
      });
    }
  }, [event.location]);

  // Calculate leave-by time and countdown
  const { leaveByTime, leaveIn } = useMemo(() => {
    if (!event.startTime || !event.travelTimeMinutes) return { leaveByTime: null, leaveIn: null };
    const [h, m] = event.startTime.split(":").map(Number);
    const start = new Date();
    start.setHours(h, m, 0, 0);
    const leaveBy = new Date(start.getTime() - event.travelTimeMinutes * 60000);
    const diffMs = leaveBy.getTime() - now;
    let leaveInStr: string | null = null;
    if (diffMs > 0) {
      const diffMins = Math.floor(diffMs / 60000);
      const hrs = Math.floor(diffMins / 60);
      const mins = diffMins % 60;
      leaveInStr = hrs > 0 ? `${hrs}H ${mins}M` : `${mins}M`;
    } else {
      leaveInStr = "NOW";
    }
    return {
      leaveByTime: leaveBy.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" }),
      leaveIn: leaveInStr,
    };
  }, [event.startTime, event.travelTimeMinutes, now]);

  // Build ticker segments with icons
  const segments: { icon: string; text: string }[] = [
    { icon: "directions-car", text: `${event.travelTimeMinutes} MIN` },
    ...(weather ? [{ icon: weather.icon || "thermostat", text: `${weather.tempF}°F` }] : []),
    ...(leaveByTime ? [{ icon: "flight-takeoff", text: `LEAVE ${leaveByTime.toUpperCase()}` }] : []),
    ...(leaveIn ? [{ icon: "timer", text: `IN ${leaveIn}` }] : []),
  ];

  const tickerHeight = 44;

  const hasStarted = useRef(false);

  // Continuous loop - start once, clean remount on event change via key
  useEffect(() => {
    if (contentWidth > 0 && !hasStarted.current) {
      hasStarted.current = true;
      translateX.value = withRepeat(
        withTiming(-contentWidth, { duration: 9000, easing: Easing.linear }),
        -1,
        false
      );
    }
  }, [contentWidth]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: translateX.value }],
  }));

  return (
    <ReAnimated.View
      entering={FadeIn.duration(250)}
      style={{ height: tickerHeight, backgroundColor: isPaper ? "#FBF7EC" : isTerminal ? TERM_PANEL : isEightBit ? "#1D1233" : "transparent", borderTopLeftRadius: isEightBit || isTerminal ? 2 : 12, borderTopRightRadius: isEightBit || isTerminal ? 2 : 12, overflow: "hidden" }}
    >
      {/* Solid outline — under Paper the strip sits on warm paper stock
          with a soft lavender edge, exactly like the approved mockup.
          Under 8-bit (v184) the outline is the mockup live strip's
          chunky 3px gold edge and the corners go square. Under
          Terminal the edge is the tube's mid green, 2px. */}
      <View style={{
        position: "absolute", top: 0, left: 0, right: 0, bottom: 0,
        borderTopWidth: isEightBit ? 3 : 2, borderLeftWidth: isEightBit ? 3 : 2, borderRightWidth: isEightBit ? 3 : 2,
        borderStyle: "solid", borderColor: isPaper ? "#D8CCF2" : isTerminal ? TERM_MID : isEightBit ? "#FFC531" : eventColor,
        borderTopLeftRadius: isEightBit || isTerminal ? 2 : 12, borderTopRightRadius: isEightBit || isTerminal ? 2 : 12,
      }} />
      <View style={{ flex: 1, justifyContent: "center", overflow: "hidden" }}>
        <ReAnimated.View
          style={[{ flexDirection: "row", alignItems: "center" }, animatedStyle]}
        >
          {[0, 1, 2].map((copy) => (
            <View
              key={copy}
              style={{ flexDirection: "row", alignItems: "center", paddingRight: 40 }}
              onLayout={copy === 0 ? (e) => {
                // Only measure first copy, once before animation starts
                if (!hasStarted.current) {
                  const w = e.nativeEvent.layout.width;
                  if (w > 0) setContentWidth(w);
                }
              } : undefined}
            >
              {segments.map((seg, i) => (
                <View key={i} style={{ flexDirection: "row", alignItems: "center", marginRight: i < segments.length - 1 ? 24 : 0 }}>
                  <MaterialIcons name={iconName(seg.icon)} size={16} color={tickerInk} />
                  <Text numberOfLines={1} style={{ color: tickerInk, fontSize: 13, fontWeight: "700", letterSpacing: 1, marginLeft: 6, ...bitDisplay(skinTokens, 9) }}>
                    {seg.text}
                  </Text>
                  {i < segments.length - 1 && (
                    <Text style={{ color: tickerInk, fontSize: 13, marginLeft: 24 }}>•</Text>
                  )}
                </View>
              ))}
              <Text style={{ color: tickerInk, fontSize: 13, marginLeft: 12 }}>•</Text>
            </View>
          ))}
        </ReAnimated.View>
      </View>
    </ReAnimated.View>
  );
}

