          <View key={"l" + i} style={{ position: "absolute", left: 2 + i * 1, top: 10 + (i % 2) * 3, width: 6, height: 2, backgroundColor: "#0A0A12", transform: [{ rotate: `${-40 + i * 26}deg` }] }} />
