  // his choice. The drawn face rests expanded; from v298 his toggles
  // persist under the new key.
  useEffect(() => {
    const loadExpandedState = async () => {
      try {
        const saved = await AsyncStorage.getItem('personalStudyExpanded.v298');
        if (saved !== null) {
          setIsPersonalStudyExpanded(saved === 'true');
        }
      } catch (e) {
        console.error('Error loading Personal Study expanded state:', e);
      }
    };
    loadExpandedState();
  }, []);

  const togglePersonalStudyExpanded = (newState: boolean) => {
    setIsPersonalStudyExpanded(newState);
    AsyncStorage.setItem('personalStudyExpanded.v298', newState ? 'true' : 'false').catch(e =>
      console.error('Error saving Personal Study expanded state:', e)
    );
  };

  // After marking a chapter read, check for book completion (+100 XP) and
  // whole-Bible completion (+1,000 XP). Triggers the celebration UI.
  const handleBookCompletionCheck = async (book: string, state: UnifiedBibleState, position?: { x: number; y: number }) => {
    if (!isBookComplete(state, book)) return state;
    const { state: updatedState, bibleComplete } = await markBookAsComplete(book);
    onAwardXP?.("book-complete", `book:${book}`, position);
    if (bibleComplete) {
      onAwardXP?.("bible-complete", "bible", position);
      setBibleFullyComplete(true);
    }
    setCelebratedBook(book);
    return updatedState;
  };

  // Reset selectedBibleStudyDay when selectedDate changes so it auto-defaults to the current day
  useEffect(() => {
    setSelectedBibleStudyDay(null);
  }, [selectedDate]);

  // Color palette for todos, events, and ministries
  const COLOR_PALETTE = [
    { name: "Gray", hex: "#6B7280" },
    { name: "Red", hex: "#EF4444" },
    { name: "Orange", hex: "#F97316" },
    { name: "Yellow", hex: "#FBBF24" },
    { name: "Green", hex: "#10B981" },
    { name: "Blue", hex: "#3B82F6" },
    { name: "Purple", hex: "#A855F7" },
  ];

  // Memoize summary data to ensure it updates when props change
  const memoizedSummaryData = useMemo(() => ({
    remainingTodos,
    remainingPrayers,
    fastingStatus,
    budgetAmount,
    peopleToReach,
    currentBibleStudy,
    personalTodos,
    onTodoComplete,
  }), [remainingTodos, remainingPrayers, fastingStatus, budgetAmount, peopleToReach, currentBibleStudy, personalTodos, onTodoComplete]);

  // Scroll animation
  const scrollY = useRef(new Animated.Value(0)).current;
  // HOTFIX (Oct 29, the v338 startup crash): the top fade rides
  // its OWN JS-driven offset (fadeScrollY), synced from this
  // screen's scrollY through a listener — the same mechanism the
  // v319 sheetAtRest listener below already uses. v338 passed
  // scrollY — a NATIVELY driven value — straight into TopFade,
  // adding the fade as a consumer of the native animated graph;
  // the fade's wiring is JS-driven only now (see
  // components/top-fade.tsx). The sheet's own scrollY keeps its
  // native driver and its direct onScroll event below, exactly
  // as before the hotfix.
  const fadeScrollY = useTopFadeScrollY();
  // v342: the tray height for the fade's edge-to-edge anchoring.
  const safeInsets = useSafeAreaInsets();
  useEffect(() => {
    const sub = scrollY.addListener(({ value }) => {
      fadeScrollY.setValue(value);
    });
    return () => scrollY.removeListener(sub);
  }, [scrollY, fadeScrollY]);
  const mainListRef = useRef<any>(null);
  // Restore scroll position on remount (lazy tab mounting).
  useEffect(() => {
    if (initialScrollY > 0 && mainListRef.current) {
      const t = setTimeout(() => {
        mainListRef.current?.scrollToOffset({ offset: initialScrollY, animated: false });
      }, 100);
      return () => clearTimeout(t);
    }
    // v297: no standing rest offset under any dress — the sheet
    // rests flush below the summary (see the note where v296's
    // rest-overlap constant stood). Its Classic-only 120px opening
    // scroll is gone with it.
  }, []);
  // v319: whether the sheet sits at rest (scrollY ≈ 0). The reach
  // press seat in the overlay host exists only in this state: at
  // rest it makes the summary panel's own "Reach out" button
  // tappable through the sheet (whose ScrollView spans the fixed
  // zone and swallows its touches); the moment the sheet moves,
  // the seat is gone, so nothing invisible is ever tappable and
  // the sliding sheet owns every touch over the zone. State flips
  // only on the rest boundary — the ref guards the listener so a
  // scroll's per-frame values never re-render this component.
  const [sheetAtRest, setSheetAtRest] = useState(true);
  const sheetAtRestRef = useRef(true);
  useEffect(() => {
    const sub = scrollY.addListener(({ value }) => {
      const atRest = value <= 0.5;
      if (atRest !== sheetAtRestRef.current) {
        sheetAtRestRef.current = atRest;
        setSheetAtRest(atRest);
      }
    });
    return () => scrollY.removeListener(sub);
  }, [scrollY]);
  // Joi-style sheet: the day-view schedule slides up as a card over the fixed summary.
  // v193: the sheet's head used to start 68px before the summary's
  // bottom edge (a standing overlap), so at rest the date header sat
  // ON the summary's tail — its last line clipped behind a box that
  // read as floating between the summary and the sheet ("Why isn't
  // it a part of the slide?", 2026-10-22). The list's header spacer
  // now gives the sheet the summary's FULL height: at rest the head
  // sits directly below the summary with none of its text covered,
  // and the slide-over still happens in motion — the summary stays
  // fixed behind the list (zIndex 0) while the sheet scrolls over it.
  // v197 (2026-10-23): his phone verdict on v193 — "Why is the
  // spacing off from the slide and the summary there? There's so
  // much more room all of the sudden?" / "There's a pretty big gap
  // on all of them now." Root cause: the spacer was never the
  // problem — the measurement is the summary wrapper's own onLayout
  // height, which is its true painted height (DailySummaryCard +
  // check-in notice + the Tasks & Events bar, inside the summary's
  // own padding). The overshoot was the FlatList content container's
  // legacy paddingTop: 90, a constant from the floating-header era
  // that predates the measured spacer. While the spacer still
  // subtracted the old 68px overlap the two roughly cancelled (net
  // height + 22); v193 removed the subtraction but left the +90, so
  // the sheet's head came to rest a guaranteed 90px BELOW the
  // summary's bottom edge on every skin — the dead band in his
  // screenshot. The padding is gone: net offset is exactly the
  // measured height, flush at rest, no overlap returns (the spacer
  // still carries the full height, so no summary text is covered),
  // and the slide-over in motion is untouched.
  const [scheduleSummaryHeight, setScheduleSummaryHeight] = useState(360);
  // v297: the Classic week strip renders LIVE in an overlay layer
  // above the sheet (see the overlay host below the day FlatList)
  // because the sheet's pointerEvents-none spacer does NOT let
  // touches fall through — the ScrollView itself stays the hit
  // target over the whole fixed zone and swallowed every tap under
  // it (his Oct 27 report: "I can't switch days"). These states
  // carry the in-summary measures: the strip layout twin's block
  // height (row + its 4px seat gap), the reach row's rect relative
  // to the summary card's root (it sizes the header slide below),
  // and — v319 — the reach row's BUTTON rect, which seats the
  // row's one press target in the overlay host. The reach row
  // itself renders once, in the panel, and never moves.
  const [classicStripHeight, setClassicStripHeight] = useState(60);
  const [classicReachRect, setClassicReachRect] = useState<{ x: number; y: number; width: number; height: number } | null>(null);
  const [classicReachButtonRect, setClassicReachButtonRect] = useState<{ x: number; y: number; width: number; height: number } | null>(null);
  // v308 (his Oct 28, 12:15, screenshot mid-scroll): "is there a
  // way to make the Date line slide up like the headers, rather
  // than shrink to the center awkwardly?" The header block's
  // collapse used to SHRINK: the overlay twins carried a scroll
  // gate that scaled them to 0.01 toward their centres as the
  // sheet's edge reached them (the week numbers visibly
  // compressed), and the app bar ghosted — opacity 1 → 0 with a
  // token 60px rise over scroll 200–320. All of that is replaced
  // by ONE slide: the app bar and the overlay strip share this
  // translateY, moving up 1:1 with the sheet's scroll until the
  // block has cleared the top edge — no scale transform. (v315
  // adds the fade back on TOP of this slide for the strip — see
  // stripFade below; the slide itself is unchanged. v319: the
  // reach twin that also rode this slide is retired — the reach
  // row renders in the panel and never moves — but the slide's
  // TRAVEL still measures the whole block, reach seat included,
  // so the app bar's shipped motion is unchanged.) The
  // geometry is self-keeping: an element's clearance above
  // the sheet's rising edge (its seat bottom vs the zone's full
  // height) is constant under a 1:1 slide, so a twin can never be
  // caught floating over the sheet's cards; and once its seat
  // bottom has scrolled past, the element sits wholly above the
  // screen's top edge — its transformed frame takes no touches,
  // so nothing invisible stays tappable. The summary panel does
  // not move: the sheet still slides over it, as the blend drew.
  // (The dead headerOpacity / DAY_HEADER_HEIGHT translate that
  // stood here unused are gone with the shrink.)
  const headerSlideFull = Math.max(
    96,
    84 + classicStripHeight,
    classicReachRect ? 84 + classicStripHeight + classicReachRect.y + classicReachRect.height : 0,
  ) + 16;
  // v328 (his Oct 28, 23:13, mid-scroll screenshot): "Can the
  // scroll for the header and date bar wait until I'm at least
  // halfway over the summary before going up?" The slide is now
  // GATED on the cover: the sheet's head spacer is exactly the
  // summary's measured height, so scrollY IS the cover distance —
  // at scrollY = scheduleSummaryHeight / 2 the sheet covers the
  // summary's first half, and until that mark the header block
  // and the strip hold their rest seats exactly (offset 0,
  // strip fully opaque): nothing moves early. From the halfway
  // mark the slide runs across the remaining cover and still
  // completes with each element having travelled its own full
  // measure, ending exactly where it ends today — header block
  // wholly above the top edge, strip fully gone — so nothing
  // lingers and nothing invisible stays tappable. Within the
  // gated range the motion is still a plain linear interpolation
  // keyed to scrollY — no springs, no bounce, no scale — and the
  // gate touches translate/opacity only, never the touch path:
  // day-switching works at every scroll position exactly as the
  // v297 overlay twin was built for, dead zone included.
  const slideGateStart = scheduleSummaryHeight / 2;
  const headerSlideY = scrollY.interpolate({
    inputRange: [slideGateStart, scheduleSummaryHeight],
    outputRange: [0, -headerSlideFull],
    extrapolate: "clamp",
  });
  // v315 (his Oct 28, 16:28 + 16:30, on v313/v314): the strip was
  // still "sitting at the top like a creep" while the list scrolled
  // under it — the shared slide's full travel is keyed to the WHOLE
  // header block (app bar + strip + reach row + margins), so on his
  // phone the strip's exit read as a linger at the top edge — and
  // he missed the fade the old shrink gate had: "I also liked that
  // it faded away as it was sliding out of the frame." So the strip
  // now completes its exit on its OWN measure: a 1:1 slide keyed to
  // its own seat (84 top + its height + 12), reaching the top edge
  // exactly as its travel ends — never further, never left hanging —
  // and a fade on the same scroll: solid through the first 45% of
  // the travel, dissolved to fully transparent exactly as the slide
  // completes. (v319: the reach twin that kept the shared
  // headerSlideY with a same-shaped fade is retired — the reach
  // row never moves now — and its fade, headerFade, is gone with
  // it; the strip's slide + fade are byte-identical to v315.) NO
  // scale anywhere (the shrink was his actual v308 complaint; the
  // fade was never the problem). Fully gone is fully gone: opacity 0
  // AND the frame wholly above the screen, so the strip neither
  // lingers visibly nor takes touches; at every earlier position
  // what is drawn is what is tappable, and day-switching works at
  // every scroll position exactly as the twin was built for.
  // (v328: slide and fade are re-based onto the gated cover range
  // — the strip holds its seat, fully opaque, until scrollY
  // reaches slideGateStart (the sheet halfway over the summary),
  // then slides its full seat measure across the remaining cover;
  // the fade keeps the v315 proportions on that gated range —
  // solid through the slide's first 45%, dissolved to 0 exactly
  // as the slide completes at full cover.)
  const stripSlideFull = 84 + classicStripHeight + 12;
  const stripSlideY = scrollY.interpolate({
    inputRange: [slideGateStart, scheduleSummaryHeight],
    outputRange: [0, -stripSlideFull],
    extrapolate: "clamp",
  });
  const stripFade = scrollY.interpolate({
    inputRange: [slideGateStart + (scheduleSummaryHeight - slideGateStart) * 0.45, scheduleSummaryHeight],
    outputRange: [1, 0],
    extrapolate: "clamp",
  });

  // Swipe between days
  const swipeTranslateX = useSharedValue(0);

  const handleSwipeLeft = useCallback(() => {
    setSelectedDate((prev) => addDays(prev, 7));
  }, []);

  const handleSwipeRight = useCallback(() => {
    setSelectedDate((prev) => addDays(prev, -7));
  }, []);

  // Week-strip swipe: horizontal swipe moves between calendar weeks
  // (same weekday, previous/next week). Vertical moves stay with the list.
  const weekStripPanResponder = useRef(
    PanResponder.create({
      onMoveShouldSetPanResponder: (_, gestureState) =>
        Math.abs(gestureState.dx) > 12 && Math.abs(gestureState.dx) > Math.abs(gestureState.dy) * 1.2,
      onPanResponderTerminationRequest: () => false,
      onPanResponderRelease: (_, gestureState) => {
        if (gestureState.dx < -45) { setWeekSlideDir(1); handleSwipeLeft(); }
        else if (gestureState.dx > 45) { setWeekSlideDir(-1); handleSwipeRight(); }
      },
    })
  ).current;



  // Helper function to parse Bible reference from text (e.g., "1 Corinthians 1" -> {book: "1 Corinthians", chapter: "1"})
  const parseBibleReference = (text: string): { book: string; chapter: string } | null => {
    // Match patterns like "1 Corinthians 1", "Genesis 5", "John 3:16", etc.
    const match = text.match(/^([A-Za-z0-9\s]+?)\s+(\d+)/);
    if (match) {
      return { book: match[1].trim(), chapter: match[2] };
    }
    return null;
  };

  // Get all unique days with Bible studies from ALL sources (bibleStudies, ministries, events)
  const getUniqueBibleStudyDays = (bibleStudiesList: BibleStudySession[], ministriesList?: ScheduleMinistry[], eventsList?: ScheduleEvent[]): Array<{ dayName: string; date: string; book: string; chapter: number }> => {
    const dayMap = new Map<string, { date: string; book: string; chapter: number }>();

    // Helper to add an item to the day map
    const addToMap = (dateStr: string, book: string, chapter: number | string) => {
      // Fix timezone: parse YYYY-MM-DD as local date, not UTC
      const parts = dateStr.split('T')[0].split('-');
      const date = parts.length === 3
        ? new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]))
        : new Date(dateStr);
      const dayName = date.toLocaleDateString('en-US', { weekday: 'long' });
      const chapterNum = typeof chapter === 'string' ? parseInt(chapter, 10) || 0 : chapter;

      const existing = dayMap.get(dayName);
      if (!existing) {
        dayMap.set(dayName, { date: dateStr, book, chapter: chapterNum });
      } else {
        const existingDate = new Date(existing.date).getTime();
        const newDate = date.getTime();
        if (newDate > existingDate) {
          dayMap.set(dayName, { date: dateStr, book, chapter: chapterNum });
        }
      }
    };

    // Add from COMPLETED Bible Study sessions only
    bibleStudiesList.filter(s => s.isCompleted).forEach(study => {
      addToMap(study.date, study.book, study.chapter);
    });

    // Add from COMPLETED Read/Bible Study ministries with Bible info
    if (ministriesList) {
      ministriesList.forEach(m => {
        if (m.isCompleted && (m.type === 'Read' || m.type === 'Bible Study') && m.bibleBook && m.bibleChapter) {
          addToMap(m.date, m.bibleBook, m.bibleChapter);
        }
      });
    }

    // Add from COMPLETED events with Bible references in title
    if (eventsList) {
      eventsList.forEach(e => {
        if (e.isCompleted && e.title) {
          const parsed = parseBibleReference(e.title);
          if (parsed) {
            addToMap(e.date, parsed.book, parsed.chapter);
          }
        }
      });
    }

    // Convert to array and sort by most recent date
    return Array.from(dayMap.entries())
      .map(([dayName, data]) => ({ dayName, ...data }))
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  };

  // Get the Bible study for a specific day
  const getBibleStudyForDay = (bibleStudiesList: BibleStudySession[], dayName: string): string => {
    // Include all Bible studies (both completed and incomplete) for day selector navigation
    const dayStudies = bibleStudiesList.filter(study => {
      const date = new Date(study.date);
      return date.toLocaleDateString('en-US', { weekday: 'long' }) === dayName;
    });

    if (dayStudies.length === 0) return 'No studies';

    // Return the most recent study for this day
    const sorted = dayStudies.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    const latest = sorted[0];
    return `${latest.book} ${latest.chapter}`;
  };

  // Helper function to get last chapter read for the selected day of week
  const getLastChapterRead = (ministriesList: ScheduleMinistry[], bibleStudiesList: BibleStudySession[], eventsList?: ScheduleEvent[], forDate?: string): string => {
    // Determine the target day of week from forDate
    let targetDayName: string | null = null;
    if (forDate) {
      const parts = forDate.split('T')[0].split('-');
      const date = parts.length === 3
        ? new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]))
        : new Date(forDate);
      targetDayName = date.toLocaleDateString('en-US', { weekday: 'long' });
    }
    // Collect all completed Bible reading items from Read ministries, Bible Study sessions, and Bible Study events
    const allReadItems: Array<{ book: string; chapter: string; date: string; completedAt?: string; dayName: string }> = [];

    // Add completed Read/Bible Study ministries with Bible info
    const readMinistries = ministriesList.filter(
      (m) => {
        if (!m.isCompleted || (m.type !== 'Read' && m.type !== 'Bible Study') || !m.bibleBook || !m.bibleChapter) return false;
        return true;
      }
    );
    readMinistries.forEach(m => {
      // Fix timezone: parse YYYY-MM-DD as local date
      const mParts = m.date.split('T')[0].split('-');
      const date = mParts.length === 3
        ? new Date(parseInt(mParts[0]), parseInt(mParts[1]) - 1, parseInt(mParts[2]))
        : new Date(m.date);
      const dayName = date.toLocaleDateString('en-US', { weekday: 'long' });
      allReadItems.push({
        book: m.bibleBook!,
        chapter: m.bibleChapter!,
        date: m.date,
        completedAt: m.completedAt,
        dayName
      });
    });

    // Add completed Bible Study sessions
    const completedStudies = bibleStudiesList.filter((s) => s.isCompleted);
    completedStudies.forEach(s => {
      // Fix timezone: parse YYYY-MM-DD as local date
      const sParts = s.date.split('T')[0].split('-');
      const date = sParts.length === 3
        ? new Date(parseInt(sParts[0]), parseInt(sParts[1]) - 1, parseInt(sParts[2]))
        : new Date(s.date);
      const dayName = date.toLocaleDateString('en-US', { weekday: 'long' });
      allReadItems.push({
        book: s.book,
        chapter: s.chapter.toString(),
        date: s.date,
        completedAt: s.completedAt,
        dayName
      });
    });

    // Add completed events that contain Bible references
    if (eventsList) {
      const completedEvents = eventsList.filter((e) => {
        if (!e.isCompleted || !e.title) return false;
        return true;
      });
      completedEvents.forEach(e => {
        const parsed = parseBibleReference(e.title);
        if (parsed) {
          // Fix timezone: parse YYYY-MM-DD as local date
          const eParts = e.date.split('T')[0].split('-');
          const date = eParts.length === 3
            ? new Date(parseInt(eParts[0]), parseInt(eParts[1]) - 1, parseInt(eParts[2]))
            : new Date(e.date);
          const dayName = date.toLocaleDateString('en-US', { weekday: 'long' });
          allReadItems.push({
            book: parsed.book,
            chapter: parsed.chapter,
            date: e.date,
            completedAt: e.completedAt,
            dayName
          });
        }
      });
    }

    if (allReadItems.length === 0) return '';

    // Filter by target day of week if specified
    const filtered = targetDayName
      ? allReadItems.filter(item => item.dayName === targetDayName)
      : allReadItems;

    if (filtered.length === 0) return '';

    // Sort by completedAt (most recent first), with date as fallback
    const sorted = filtered.sort((a, b) => {
      const timeA = a.completedAt ? new Date(a.completedAt).getTime() : new Date(a.date).getTime();
      const timeB = b.completedAt ? new Date(b.completedAt).getTime() : new Date(b.date).getTime();
      return timeB - timeA; // Most recent first
    });

    const latest = sorted[0];
    return `${latest.book} ${latest.chapter}`
  };

  // Load data
  useEffect(() => {
    const loadData = async () => {
      try {
        const [eventsData, todosData, ministriesData, bibleStudiesData, timeBlockColorsData, worshipListsData, worshipLinksData, prayersData, worshipExpansionData, worshipTrackCompletionsData] = await Promise.all([
          AsyncStorage.getItem(SCHEDULE_EVENTS_KEY),
          AsyncStorage.getItem(SCHEDULE_TODOS_KEY),
          AsyncStorage.getItem(SCHEDULE_MINISTRIES_KEY),
          AsyncStorage.getItem(SCHEDULE_BIBLE_STUDIES_KEY),
          AsyncStorage.getItem('SCHEDULE_TIME_BLOCK_COLORS_KEY'),
          AsyncStorage.getItem(WORSHIP_LISTS_KEY),
          AsyncStorage.getItem('WORSHIP_LIST_LINKS_KEY'),
          AsyncStorage.getItem('PRAYERS_KEY'),
          AsyncStorage.getItem(WORSHIP_EXPANSION_STATE_KEY),
          AsyncStorage.getItem(WORSHIP_TRACK_COMPLETION_STATE_KEY),
        ]);
        if (eventsData) setEvents(JSON.parse(eventsData));
        if (todosData) setTodos(JSON.parse(todosData));
        if (ministriesData) setMinistries(JSON.parse(ministriesData));
        if (bibleStudiesData) setBibleStudies(JSON.parse(bibleStudiesData));
        if (timeBlockColorsData) setTimeBlockColors(JSON.parse(timeBlockColorsData));
        if (worshipListsData) setWorshipLists(JSON.parse(worshipListsData));
        if (worshipLinksData) setWorshipListLinks(JSON.parse(worshipLinksData));
        if (prayersData) setPrayers(JSON.parse(prayersData));
        if (worshipExpansionData) {
          const parsedExpansion = JSON.parse(worshipExpansionData);
          if (parsedExpansion && typeof parsedExpansion === 'object' && !Array.isArray(parsedExpansion)) {
            const normalizedExpansion = Object.entries(parsedExpansion).reduce<Record<string, boolean>>((result, [date, expanded]) => {
              if (/^\d{4}-\d{2}-\d{2}$/.test(date) && typeof expanded === 'boolean') {
                result[date] = expanded;
              }
              return result;
            }, {});
            setWorshipExpansionByDate(normalizedExpansion);
          }
        }
        if (worshipTrackCompletionsData) {
          const parsedCompletions = JSON.parse(worshipTrackCompletionsData);
          if (parsedCompletions && typeof parsedCompletions === 'object' && !Array.isArray(parsedCompletions)) {
            setWorshipTrackCompletions(
              Object.entries(parsedCompletions).reduce<Record<string, boolean>>((result, [key, completed]) => {
                if (typeof key === 'string' && typeof completed === 'boolean') result[key] = completed;
                return result;
              }, {}),
            );
          }
        }
        const timeOffData = await getAllTimeOff();
        setTimeOffList(timeOffData);
      } catch (e) {
        // Silent fail
      } finally {
        setIsScheduleHydrated(true);
        setIsWorshipExpansionHydrated(true);
        setIsWorshipTrackCompletionsHydrated(true);
      }
    };
    loadData();
  }, []);

  // Save data
  useEffect(() => {
    if (!isScheduleHydrated) return;
    AsyncStorage.setItem(SCHEDULE_EVENTS_KEY, JSON.stringify(events)).catch(() => undefined);
  }, [isScheduleHydrated, events]);

  useEffect(() => {
    syncScheduledEventNotifications(events, todos, ministries).catch(() => undefined);
  }, [defaultEventReminderMinutes, eventRemindersEnabled, events, ministries, todos]);

  useEffect(() => {
    AsyncStorage.setItem('WORSHIP_LIST_LINKS_KEY', JSON.stringify(worshipListLinks)).catch(() => undefined);
  }, [worshipListLinks]);
  useEffect(() => {
    if (!isScheduleHydrated) return;
    AsyncStorage.setItem(SCHEDULE_TODOS_KEY, JSON.stringify(todos)).catch(() => undefined);
  }, [isScheduleHydrated, todos]);

  useEffect(() => {
    AsyncStorage.setItem('PRAYERS_KEY', JSON.stringify(prayers)).catch(() => undefined);
  }, [prayers]);
  useEffect(() => {
    if (!isScheduleHydrated) return;
    AsyncStorage.setItem(SCHEDULE_MINISTRIES_KEY, JSON.stringify(ministries)).catch(() => undefined);
  }, [isScheduleHydrated, ministries]);
  useEffect(() => {
    if (!isScheduleHydrated) return;
    AsyncStorage.setItem(SCHEDULE_BIBLE_STUDIES_KEY, JSON.stringify(bibleStudies)).catch(() => undefined);
  }, [isScheduleHydrated, bibleStudies]);
  useEffect(() => {
    if (!isScheduleHydrated) return;
    AsyncStorage.setItem('SCHEDULE_TIME_BLOCK_COLORS_KEY', JSON.stringify(timeBlockColors)).catch(() => undefined);
  }, [isScheduleHydrated, timeBlockColors]);

  useEffect(() => {
    if (!isWorshipExpansionHydrated) return;
    AsyncStorage.setItem(WORSHIP_EXPANSION_STATE_KEY, JSON.stringify(worshipExpansionByDate)).catch(() => undefined);
  }, [isWorshipExpansionHydrated, worshipExpansionByDate]);

  useEffect(() => {
    if (!isWorshipTrackCompletionsHydrated) return;
    AsyncStorage.setItem(WORSHIP_TRACK_COMPLETION_STATE_KEY, JSON.stringify(worshipTrackCompletions)).catch(() => undefined);
  }, [isWorshipTrackCompletionsHydrated, worshipTrackCompletions]);

  // Derived data for selected date
  const dateHeader = useMemo(() => formatDateHeader(selectedDate), [selectedDate]);
  const weekDates = useMemo(() => getWeekDates(selectedDate), [selectedDate]);
  const dayEvents = useMemo(() => {
    const isTimeOffDay = isDateDuringTimeOff(timeOffList, selectedDate);
    const base = getEventsForDate(events, selectedDate).filter((event) => isTimeOffEventVisible(event, isTimeOffDay));
    if (!holidaysEnabled) return base;
    // Auto-seeded US holidays: render-only synthetic events. They carry no
    // startTime (so white-space blocks ignore them) and are never written
    // back to state, storage, notifications, or export.
    const year = parseInt(selectedDate.slice(0, 4), 10);
    if (Number.isNaN(year)) return base;
    const holidayEvents: ScheduleEvent[] = getHolidaysForYear(year)
      .filter((h) => h.date === selectedDate)
      .map((h) => ({
        id: `holiday-${h.date}-${h.name}`,
        title: h.name,
        date: selectedDate,
        keyword: h.keyword || undefined,
        isHoliday: true,
        isCompleted: false,
      }));
    return [...base, ...holidayEvents];
  }, [events, selectedDate, timeOffList, holidaysEnabled]);
  const dayTodos = useMemo(() => getTodosForDate(todos, selectedDate), [todos, selectedDate]);
  const dayMinistries = useMemo(() => getMinistriesForDate(ministries, selectedDate), [ministries, selectedDate]);
  const dayBirthdays = useMemo(() => getBirthdaysForDate(people, selectedDate), [people, selectedDate]);
  const prayerCheckInPeople = useMemo(() => getPrayerCheckInPeople(people, selectedDate), [people, selectedDate]);
  const missedTodos = useMemo(() => {
    const selectedDateStr = formatDateLocal(new Date(selectedDate));
    return todos
      .filter((todo) => formatDateLocal(new Date(todo.date)) < selectedDateStr && !todo.isCompleted)
      .sort((first, second) => first.date.localeCompare(second.date));
  }, [selectedDate, todos]);

  useEffect(() => {
    if (missedTodos.length === 0) {
      setIsMissedTodosOpen(false);
      setActiveMissedTodoId(null);
      return;
    }

    if (activeMissedTodoId && !missedTodos.some((todo) => todo.id === activeMissedTodoId)) {
      setActiveMissedTodoId(null);
    }
  }, [activeMissedTodoId, missedTodos]);

  // Fasting info for expandable card
  const activeFast = useMemo(() => getActiveFast(fasts, selectedDate), [fasts, selectedDate]);

  // Current Bible book and full state from AsyncStorage
  const [currentBibleBook, setCurrentBibleBook] = useState<string | null>(null);
  const [bibleState, setBibleState] = useState<UnifiedBibleState | null>(null);

  // v205: the Personal Study card's lines come from the NEW study store
  // (the same store the Books view, chapter page and queue read). The
  // first load also runs the one-time migration of his old check-offs.
  // v211: the card's POSITION comes from that store too — the snapshot
  // below feeds getReadingPosition (position.ts); the unified store is
  // out of the card entirely. And the doorway sub-line is retired: the
  // card no longer navigates anywhere on tap, so "Tap to open your
  // Books" would be a lie — only real queue lines ride the sub now.
  const [studyDoorway, setStudyDoorway] = useState<{ line: string; sub: string | null } | null>(null);
  const [studySnap, setStudySnap] = useState<StudyState | null>(null);
  const refreshStudyCard = useCallback(() => {
    loadV205StudyState()
      .then((state) => {
        setStudySnap(state);
        let complete = 0;
        for (const book of Object.keys(V205_CHAPTER_COUNTS)) {
          const total = v205ChapterCountFor(book);
          for (let c = 1; c <= total; c++) {
            if (v205ChapterStatus(state, book, c) === "complete") complete++;
          }
        }
        const nextWrite = state.writeQueue[0];
        const nextRestudy = state.restudyQueue[0];
        setStudyDoorway({
          line: complete > 0 ? `${complete} chapter${complete === 1 ? "" : "s"} complete` : "Your Books",
          sub: nextWrite
            ? `Next to write: ${nextWrite.book} ${nextWrite.chapter}`
            : nextRestudy
              ? `To re-study: ${nextRestudy.book} ${nextRestudy.chapter}`
              : null,
        });
      })
      .catch(() => undefined);
  }, []);
  useEffect(() => {
    refreshStudyCard();
  }, [bibleState, refreshStudyCard]);

  // v211: the restored Back button — step the current book's highest
  // Complete chapter back to None, through the same one door every
  // status change walks (transitionChapterStatus). No XP is revoked,
  // ever; lastRead does not move — the target re-derives from the
  // statuses, so the chapter he stepped back from is next again.
  const handlePersonalStudyBack = async (book: string) => {
    try {
      const study = await loadV205StudyState();
      const total = v205ChapterCountFor(book);
      let target: number | null = null;
      for (let c = total; c >= 1; c--) {
        if (v205ChapterStatus(study, book, c) === "complete") {
          target = c;
          break;
        }
      }
      if (target == null) return;
      await transitionChapterStatus(study, book, target, "none");
      refreshStudyCard();
    } catch (e) {
      console.error("Error stepping back a chapter:", e);
    }
  };

  // v273: the study card's Mark as Read — his ask (Oct 26 12:11):
  // the expanded row's big Bible doorway becomes a Mark as Read
  // button for the headline chapter, so the mark happens where he
  // already is. Same discipline as the Back button above: fresh
  // study state at press time, the toggle decided from that state's
  // own read mark, studio imports loaded fresh (the chapter page
  // passes its in-memory copies of the same two inputs), and the
  // mark itself walks the ONE read door — markChapterRead /
  // unmarkChapterRead from bible-v205/rewards, the two-marks
  // authority (+25 XP once, never revoked). The legacy unified
  // markChapterAsRead is never touched here. Marking read advances
  // the card's position on refresh (the target is by derivation
  // the next unread chapter), exactly as reading on the chapter
  // page does.
  const handlePersonalStudyMarkRead = async (book: string, chapter: number) => {
    try {
      const study = await loadV205StudyState();
      if (v205ChapterReadDate(study, book, chapter) !== null) {
        await unmarkChapterRead(study, book, chapter);
      } else {
        const imports = await loadStudioImports().catch(() => ({}));
        await markChapterRead(study, book, chapter, undefined, imports);
      }
      refreshStudyCard();
    } catch (e) {
      console.error("Error toggling the study card's read mark:", e);
    }
  };

  // Sync currentBibleBook whenever bibleState changes.
  // v207: the pre-v205 card fetched its storyteller preview live from
  // the bible.getChapterSummary tRPC route and cached it per chapter;
  // v205 cut the display but left this fetch running unwatched. The
  // fetch is now retired for good — the previews ship baked into the
  // app as local data (lib/bible-v205/previews.ts, composed by
  // lib/bible-v205/preview.ts) and the card reads them synchronously.
  // The server route itself is untouched; the card no longer calls it.
  useEffect(() => {
    if (bibleState) {
      const display = getCurrentBibleDisplay(bibleState);
      setCurrentBibleBook(display || 'No book marked as current');
    }
  }, [bibleState]);

  useEffect(() => {
    const loadBibleData = async () => {
      try {
        // Try to load unified Bible state first
        let state: UnifiedBibleState | null = null;
        const unifiedData = await AsyncStorage.getItem(UNIFIED_BIBLE_KEY);

        if (unifiedData) {
          state = JSON.parse(unifiedData);
          if (state) console.log('Unified Bible data loaded:', { display: getCurrentBibleDisplay(state), bookStatuses: state.bookStatuses });
        } else {
          // Fallback: check for legacy book status and chapters
          const legacyBookStatus = await AsyncStorage.getItem('bibleBookStatus');
          const legacyChapters = await AsyncStorage.getItem('bibleChapters');

          if (legacyBookStatus || legacyChapters) {
            const legacyStatuses = legacyBookStatus ? JSON.parse(legacyBookStatus) : {};
            const legacyChapterData = legacyChapters ? JSON.parse(legacyChapters) : [];
            console.log('Found legacy data, migrating:', { legacyStatuses, chapterCount: legacyChapterData.length });

            // Convert legacy chapters to new format with readDate
            const yesterday = new Date();
            yesterday.setDate(yesterday.getDate() - 1);
            const yesterdayStr = yesterday.toISOString().split('T')[0];

            const migratedChapters = legacyChapterData.map((ch: any) => ({
              book: ch.book,
              chapter: ch.chapter,
              isRead: ch.isRead || false,
              readDate: ch.isRead ? yesterdayStr : undefined,
              isBookmarked: ch.isBookmarked || false,
            }));

            // Create a new unified state with the legacy data
            state = {
              chapters: migratedChapters,
              bookStatuses: legacyStatuses,
            };

            // Save migrated state to unified storage
            await AsyncStorage.setItem(UNIFIED_BIBLE_KEY, JSON.stringify(state));
          }
        }

        if (state && state.bookStatuses) {
          // Ensure chapters array exists and is populated
          if (!state.chapters || state.chapters.length === 0) {
            console.log('Initializing empty chapters array');
            const { initializeUnifiedBible } = await import('@/lib/bible-unified');
            state = await initializeUnifiedBible();
          }
          setBibleState(state);
          const display = getCurrentBibleDisplay(state);
          if (display) setCurrentBibleBook(display);
          else setCurrentBibleBook('No book marked as current');
        } else {
          console.log('No Bible data found in either storage system');
          setCurrentBibleBook('No book marked as current');
        }
      } catch (e) {
        console.error('Error loading Bible data:', e);
        setCurrentBibleBook('Error loading Bible data');
      }
    };

    loadBibleData();
  }, []);

  // Profile data from AsyncStorage - use canonical PROFILE_STORAGE_KEY
  const [userName, setUserName] = useState("Friend");
  const [userProfilePhoto, setUserProfilePhoto] = useState<string | undefined>(undefined);
  const [prayerStreak, setPrayerStreak] = useState(0);

  const loadProfileData = useCallback(() => {
    AsyncStorage.getItem(PROFILE_STORAGE_KEY).then((data) => {
      if (data) {
        try {
          const profile = JSON.parse(data);
          if (profile.name) setUserName(profile.name);
          if (profile.photoUri) setUserProfilePhoto(profile.photoUri);
        } catch (e) {
          // Silent fail
        }
      }
    }).catch(() => undefined);
  }, []);

  useEffect(() => {
    loadProfileData();
  }, [loadProfileData]);

  // Listen for Bible chapter marked read events and refresh immediately
  useEffect(() => {
    const unsubscribe = bibleEventEmitter.subscribe(async (event) => {
      if (event.type === 'chapter-marked-read') {
        // Reload Bible data immediately
        try {
          const unifiedData = await AsyncStorage.getItem(UNIFIED_BIBLE_KEY);
          if (unifiedData) {
            const state = JSON.parse(unifiedData) as UnifiedBibleState;
            setBibleState(state);
            const display = getCurrentBibleDisplay(state);
            if (display) setCurrentBibleBook(display);
          }
        } catch (e) {
          console.error('Error refreshing Bible data on chapter marked read:', e);
        }
      }
    });

    return () => unsubscribe();
  }, []);

  // Reload profile and Bible book when tab comes into focus
  useFocusEffect(
    useCallback(() => {
      loadProfileData();
      // v211: the Personal Study card reads the study store — reload it
      // on focus too, so a chapter completed on the chapter page moves
      // the card's position the moment he comes back.
      refreshStudyCard();

      // v336: the News/Email pages' Finished button completes an
      // event in storage while this tab sits behind them — reload
      // the events on focus too (the same v211 pattern), so the day
      // page shows the event completed the moment he returns
      // instead of the write being clobbered by this tab's next
      // save from its stale in-memory list.
      // v365: the same protection now covers todos and ministries.
      // The studio import doors (manual + Drive) write all three
      // stores directly; before v365 only events were re-read here,
      // so an imported todo/ministry change could be overwritten by
      // this tab's next save from its stale in-memory lists. All
      // three lists are re-read on focus, before he can interact.
      (async () => {
        try {
          const storedEvents = await AsyncStorage.getItem(SCHEDULE_EVENTS_KEY);
          if (storedEvents) setEvents(JSON.parse(storedEvents));
          const storedTodos = await AsyncStorage.getItem(SCHEDULE_TODOS_KEY);
          if (storedTodos) setTodos(JSON.parse(storedTodos));
          const storedMinistries = await AsyncStorage.getItem(SCHEDULE_MINISTRIES_KEY);
          if (storedMinistries) setMinistries(JSON.parse(storedMinistries));
        } catch {
          // A failed reload leaves the in-memory lists as they were.
        }
      })();

      const reloadBibleData = async () => {
        try {
          // Try to load unified Bible state first
          let state: UnifiedBibleState | null = null;
          const unifiedData = await AsyncStorage.getItem(UNIFIED_BIBLE_KEY);

          if (unifiedData) {
            state = JSON.parse(unifiedData);
            if (state) console.log('Unified Bible data reloaded on focus:', { display: getCurrentBibleDisplay(state), bookStatuses: state.bookStatuses });
          } else {
            // Fallback: check for legacy book status
            const legacyBookStatus = await AsyncStorage.getItem('bibleBookStatus');
            if (legacyBookStatus) {
              const legacyStatuses = JSON.parse(legacyBookStatus);
              console.log('Found legacy book status on focus, migrating:', legacyStatuses);

              // Create a new unified state with the legacy book statuses
              state = {
                chapters: [],
                bookStatuses: legacyStatuses,
              };

              // Save migrated state to unified storage
              await AsyncStorage.setItem(UNIFIED_BIBLE_KEY, JSON.stringify(state));
            }
          }

          if (state && state.bookStatuses) {
            setBibleState(state);
            const display = getCurrentBibleDisplay(state);
            if (display) setCurrentBibleBook(display);
            else setCurrentBibleBook('No book marked as current');
          } else {
            setCurrentBibleBook('No book marked as current');
          }
        } catch (e) {
          console.error('Error reloading Bible data:', e);
        }
      };

      reloadBibleData();
    }, [loadProfileData, refreshStudyCard])
  );

  // Form handlers
  const handleFormStartTimeChange = (startTime: string) => {
    setFormStartTime(startTime);
    if (!formEndTime && startTime) {
      setFormEndTime(minutesToTime(Math.min(timeToMinutes(startTime) + 60, 23 * 60 + 59)));
    }
  };

